import { query } from "convex:/_system/repl/wrappers.js";

export default query({
  handler: async (ctx) => {
    const goldenRuns = await ctx.db.query("golden_task_runs").collect();
    const goldenTaskIds = new Set(goldenRuns.map((r) => r.task_id));
    const allTasks = await ctx.db.query("tasks").collect();
    const organic = allTasks.filter((t) => !goldenTaskIds.has(t._id) && !t.parent_task_id);
    return organic.map((t) => ({
      task_id: t._id,
      created_at: t._creationTime,
      prompt: (t.prompt ?? "").slice(0, 1500),
      prompt_len: (t.prompt ?? "").length,
      task_type: t.task_type,
      max_budget: t.max_budget,
      bid_window_seconds: t.bid_window_seconds,
      posted_by: t.posted_by,
      status: t.status,
    }));
  },
});
